insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('62045ea4-d9a5-498b-aaa0-806778b442bf', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'The Design Process', 'This section teaches design as a disciplined creative cycle. Students learn how an initial response to a script becomes a tested, communicable, buildable design proposal.', 0),
  ('e0eb5007-d489-47b6-be46-da5e9e7d6d7c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '62045ea4-d9a5-498b-aaa0-806778b442bf', 'subtopic'::public.curated_course_node_type, 'First response and design questions', 'The point is to capture instinct before analysis flattens it. Designers learn to name curiosity, discomfort, attraction, and the questions that will guide research.', 0),
  ('d35d0b46-cdce-489f-9a43-3188e25c4a6d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e0eb5007-d489-47b6-be46-da5e9e7d6d7c', 'concept'::public.curated_course_node_type, 'Image and emotional response', null, 0),
  ('1b61a5bf-eae6-453b-8cec-5c537fe2221f', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e0eb5007-d489-47b6-be46-da5e9e7d6d7c', 'concept'::public.curated_course_node_type, 'Questions for director and dramaturg', null, 1),
  ('721e463e-d8f5-4e28-8542-3eb024861dbe', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e0eb5007-d489-47b6-be46-da5e9e7d6d7c', 'concept'::public.curated_course_node_type, 'Early constraints and opportunities', null, 2),
  ('33e817c4-b3a1-490b-9b89-03130b73832d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '62045ea4-d9a5-498b-aaa0-806778b442bf', 'subtopic'::public.curated_course_node_type, 'Research and dramaturgical inquiry', 'Research gives the design a world beyond taste. Students learn to gather visual, historical, cultural, material, and sensory evidence.', 1),
  ('cbede6fd-ed48-4136-943f-fda87f2a1c7e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '33e817c4-b3a1-490b-9b89-03130b73832d', 'concept'::public.curated_course_node_type, 'Primary and secondary sources', null, 0),
  ('b8f50494-ef19-4d64-abe2-f5751afd6c9b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '33e817c4-b3a1-490b-9b89-03130b73832d', 'concept'::public.curated_course_node_type, 'Visual culture and period research', null, 1),
  ('709dc874-307a-4f49-a190-51dff46ecd30', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '33e817c4-b3a1-490b-9b89-03130b73832d', 'concept'::public.curated_course_node_type, 'Cultural specificity and ethical research', null, 2),
  ('f4701020-6943-449f-b3e8-bbeda3c091e4', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '62045ea4-d9a5-498b-aaa0-806778b442bf', 'subtopic'::public.curated_course_node_type, 'Concept development', 'Concept turns research into a clear design argument. Students practice moving from many references to one coherent production idea.', 2),
  ('3820d976-ade0-4757-abb4-8b70dd33b38e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f4701020-6943-449f-b3e8-bbeda3c091e4', 'concept'::public.curated_course_node_type, 'Metaphor and organizing image', null, 0),
  ('5622b615-9e2c-48b4-9465-14e939ef6024', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f4701020-6943-449f-b3e8-bbeda3c091e4', 'concept'::public.curated_course_node_type, 'Style, tone, and theatrical rules', null, 1),
  ('6be9667e-591b-4f10-b071-d1f0958f9218', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f4701020-6943-449f-b3e8-bbeda3c091e4', 'concept'::public.curated_course_node_type, 'Concept statements and design vocabulary', null, 2),
  ('e720c304-7234-4a88-b295-40eb74be8676', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '62045ea4-d9a5-498b-aaa0-806778b442bf', 'subtopic'::public.curated_course_node_type, 'Iteration and critique', 'Design improves through revision. Students learn to test choices, receive critique, and refine without losing the core idea.', 3),
  ('bf48e50a-c310-4f46-a064-1afac0253f4e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e720c304-7234-4a88-b295-40eb74be8676', 'concept'::public.curated_course_node_type, 'Thumbnail studies', null, 0),
  ('ca03af6f-d3a3-4905-b2c1-70c2785e888e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e720c304-7234-4a88-b295-40eb74be8676', 'concept'::public.curated_course_node_type, 'Peer critique protocols', null, 1),
  ('04ad077f-c725-4878-a2e5-6902b5ab22df', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e720c304-7234-4a88-b295-40eb74be8676', 'concept'::public.curated_course_node_type, 'Revision logs and decision rationale', null, 2),
  ('5cea4df6-7563-4938-8d45-622b65f96c28', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Script Analysis for Designers', 'Designers read scripts for visible and invisible demands: space, time, action, atmosphere, bodies, sound, objects, and transformation.', 1),
  ('4bdaaaac-5228-421d-bcb1-8139ce0dab08', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5cea4df6-7563-4938-8d45-622b65f96c28', 'subtopic'::public.curated_course_node_type, 'Given circumstances and world of the play', 'Students learn to identify the facts that every design must honor or intentionally transform.', 0),
  ('c481b38b-1630-4abd-8097-dea20369b5fb', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '4bdaaaac-5228-421d-bcb1-8139ce0dab08', 'concept'::public.curated_course_node_type, 'Place and period', null, 0),
  ('d0580d9e-8afd-488c-bb1a-546ffc47c28c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '4bdaaaac-5228-421d-bcb1-8139ce0dab08', 'concept'::public.curated_course_node_type, 'Social class and institutions', null, 1),
  ('23681f53-5284-45db-be7d-508f53b04f08', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '4bdaaaac-5228-421d-bcb1-8139ce0dab08', 'concept'::public.curated_course_node_type, 'Weather, season, and time', null, 2),
  ('32e7c738-8df3-4bef-b441-1af8f47bb6cc', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5cea4df6-7563-4938-8d45-622b65f96c28', 'subtopic'::public.curated_course_node_type, 'Dramatic action and structure', 'The goal is to understand how design supports conflict, change, and rhythm rather than decorating scenes.', 1),
  ('c32dd2d1-d5b1-4c45-92dc-afb3bbd8e45d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '32e7c738-8df3-4bef-b441-1af8f47bb6cc', 'concept'::public.curated_course_node_type, 'Events and turning points', null, 0),
  ('0c608bb4-4123-4e87-b398-3c50a8186d9e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '32e7c738-8df3-4bef-b441-1af8f47bb6cc', 'concept'::public.curated_course_node_type, 'Beats and tempo', null, 1),
  ('2268e287-f22c-48dc-b942-29f095e2735f', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '32e7c738-8df3-4bef-b441-1af8f47bb6cc', 'concept'::public.curated_course_node_type, 'Scene transitions', null, 2),
  ('95631db5-3ef3-425f-ac08-14d262328188', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5cea4df6-7563-4938-8d45-622b65f96c28', 'subtopic'::public.curated_course_node_type, 'Character and social identity', 'Design choices reveal how characters move through status, desire, labor, culture, and community.', 2),
  ('123d7fc8-11be-48a8-8e6a-fb6a3c41b388', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '95631db5-3ef3-425f-ac08-14d262328188', 'concept'::public.curated_course_node_type, 'Character research', null, 0),
  ('92b9c75d-94c4-4959-8970-99c17b014e44', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '95631db5-3ef3-425f-ac08-14d262328188', 'concept'::public.curated_course_node_type, 'Costume and object biographies', null, 1),
  ('506ec214-528d-4be1-915b-52236e590b61', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '95631db5-3ef3-425f-ac08-14d262328188', 'concept'::public.curated_course_node_type, 'Power, identity, and representation', null, 2),
  ('2add15fd-8c4c-4caa-9bdb-5ef4405db0b2', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5cea4df6-7563-4938-8d45-622b65f96c28', 'subtopic'::public.curated_course_node_type, 'Designable moments', 'Students identify where scenery, light, costume, sound, and props can actively tell the story.', 3),
  ('3171759a-7381-4244-b46b-3d3eade4e546', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2add15fd-8c4c-4caa-9bdb-5ef4405db0b2', 'concept'::public.curated_course_node_type, 'Entrances and exits', null, 0),
  ('ef9f5d35-2a45-45d8-918f-507263835f8b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2add15fd-8c4c-4caa-9bdb-5ef4405db0b2', 'concept'::public.curated_course_node_type, 'Reveals and transformations', null, 1),
  ('46f00e40-db20-43c1-bdf2-089fe99b97fe', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2add15fd-8c4c-4caa-9bdb-5ef4405db0b2', 'concept'::public.curated_course_node_type, 'Silence, darkness, and sonic shifts', null, 2),
  ('b97da1ff-78ac-49af-9d5d-3b480d903a58', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Scenic Design Fundamentals', 'Scenic design gives the production a spatial argument. Students learn how scale, architecture, texture, line, and movement shape the audience''s reading of the play.', 2),
  ('e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b97da1ff-78ac-49af-9d5d-3b480d903a58', 'subtopic'::public.curated_course_node_type, 'Stage space and composition', 'Students learn how the audience reads space and how a set can organize attention, status, and action.', 0),
  ('adeb06fa-dad8-4650-805b-a4855c95f637', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4', 'concept'::public.curated_course_node_type, 'Proportion and balance', null, 0),
  ('e8ff1870-8465-4b29-8029-ecd648b2fd88', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4', 'concept'::public.curated_course_node_type, 'Sightlines and focus', null, 1),
  ('b1fa1bc8-3ee5-43ec-b637-142709326a37', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4', 'concept'::public.curated_course_node_type, 'Positive and negative space', null, 2),
  ('9e0282ab-c0f9-404d-93cc-ea223c834285', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b97da1ff-78ac-49af-9d5d-3b480d903a58', 'subtopic'::public.curated_course_node_type, 'Ground plans and models', 'The point is to make ideas testable. Students translate imagination into scaled documents that directors, actors, and shops can use.', 1);
