values
  ('b9105237-a148-4c29-9ea0-76a29fb2d448', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9e0282ab-c0f9-404d-93cc-ea223c834285', 'concept'::public.curated_course_node_type, 'Scale and measurement', null, 0),
  ('e4c1f1ac-cd35-40c6-bd9d-d0c2f57c24ca', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9e0282ab-c0f9-404d-93cc-ea223c834285', 'concept'::public.curated_course_node_type, 'Traffic and blocking', null, 1),
  ('d9cffab3-e6dc-4afc-a0b0-49945f674148', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9e0282ab-c0f9-404d-93cc-ea223c834285', 'concept'::public.curated_course_node_type, 'White models and presentation models', null, 2),
  ('a612d6bc-e473-4d3e-8c43-b4e45e649b8f', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b97da1ff-78ac-49af-9d5d-3b480d903a58', 'subtopic'::public.curated_course_node_type, 'Materials, texture, and color', 'Scenic surfaces carry meaning and practical consequences. Students connect aesthetic choices to budget, build, durability, and theatrical illusion.', 2),
  ('6c1c7521-93d8-4dcc-aac4-a2c740c63ede', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a612d6bc-e473-4d3e-8c43-b4e45e649b8f', 'concept'::public.curated_course_node_type, 'Paint treatments', null, 0),
  ('47171746-382d-4a31-a5aa-8ea62655bcb2', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a612d6bc-e473-4d3e-8c43-b4e45e649b8f', 'concept'::public.curated_course_node_type, 'Fabrication materials', null, 1),
  ('943e0b1f-40cd-4305-8258-b42fedca1c5e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a612d6bc-e473-4d3e-8c43-b4e45e649b8f', 'concept'::public.curated_course_node_type, 'Palette and visual metaphor', null, 2),
  ('b745b9e8-d874-4d97-9098-1c340d437941', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b97da1ff-78ac-49af-9d5d-3b480d903a58', 'subtopic'::public.curated_course_node_type, 'Scene shifts and stage mechanics', 'Design includes how the world changes. Students study transitions as part of storytelling, not just logistics.', 3),
  ('817a7435-bdfe-4e47-87f0-7e52b006a35e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b745b9e8-d874-4d97-9098-1c340d437941', 'concept'::public.curated_course_node_type, 'Wagons, tracks, and turntables', null, 0),
  ('e7119e67-04d5-43d4-9759-6d8bd41c8601', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b745b9e8-d874-4d97-9098-1c340d437941', 'concept'::public.curated_course_node_type, 'Flying and rigging basics', null, 1),
  ('9e9ded99-f4e9-45e2-97ca-b1301e75687a', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'b745b9e8-d874-4d97-9098-1c340d437941', 'concept'::public.curated_course_node_type, 'Crew choreography and safety', null, 2),
  ('2d23a482-137a-4edd-b53e-0aa2e39be189', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Lighting Design Fundamentals', 'Lighting makes the audience see, feel, and follow. Students learn how angle, color, intensity, time, and cue structure create the visual score of performance.', 3),
  ('6ba49b09-7827-4cf8-8638-87b215553b8c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2d23a482-137a-4edd-b53e-0aa2e39be189', 'subtopic'::public.curated_course_node_type, 'Functions of stage lighting', 'Students learn the practical and expressive purposes of light: visibility, focus, form, mood, rhythm, and environment.', 0),
  ('8ab855e2-3472-43b9-9d38-17903089d7f3', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '6ba49b09-7827-4cf8-8638-87b215553b8c', 'concept'::public.curated_course_node_type, 'Visibility and selective focus', null, 0),
  ('3566beaf-712d-40af-9a73-66b29b7f8086', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '6ba49b09-7827-4cf8-8638-87b215553b8c', 'concept'::public.curated_course_node_type, 'Modeling bodies and space', null, 1),
  ('d4452ee9-c09d-44b7-8196-9bfcade9ba48', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '6ba49b09-7827-4cf8-8638-87b215553b8c', 'concept'::public.curated_course_node_type, 'Mood, style, and atmosphere', null, 2),
  ('afd3e397-75a4-44eb-83c8-256f0cf86665', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2d23a482-137a-4edd-b53e-0aa2e39be189', 'subtopic'::public.curated_course_node_type, 'Color, angle, and instrument basics', 'The point is to understand the tools before composing with them. Students connect equipment choices to visual effect.', 1),
  ('b50179e3-7ac6-4193-8389-2f42530b7c2d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'afd3e397-75a4-44eb-83c8-256f0cf86665', 'concept'::public.curated_course_node_type, 'Fixture families', null, 0),
  ('f802da3e-ba78-45f2-875d-cedd862abb8d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'afd3e397-75a4-44eb-83c8-256f0cf86665', 'concept'::public.curated_course_node_type, 'Hanging positions', null, 1),
  ('dbd517e2-70ba-4fc4-ae8c-3b7150c4db3c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'afd3e397-75a4-44eb-83c8-256f0cf86665', 'concept'::public.curated_course_node_type, 'Gel, LED color, and color temperature', null, 2),
  ('52fcb0c2-6983-4ea0-8251-4fa0d88a87f7', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2d23a482-137a-4edd-b53e-0aa2e39be189', 'subtopic'::public.curated_course_node_type, 'Cueing and time', 'Lighting design unfolds in time. Students practice making transitions that support dramatic rhythm and audience attention.', 2),
  ('810adbec-c90f-4d34-8b1e-451833c71af3', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '52fcb0c2-6983-4ea0-8251-4fa0d88a87f7', 'concept'::public.curated_course_node_type, 'Cue structure', null, 0),
  ('75c33981-48e8-40e4-9297-d3001632a2ab', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '52fcb0c2-6983-4ea0-8251-4fa0d88a87f7', 'concept'::public.curated_course_node_type, 'Fades and blackouts', null, 1),
  ('ef89cf78-2988-4418-876e-8e10036c5a8e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '52fcb0c2-6983-4ea0-8251-4fa0d88a87f7', 'concept'::public.curated_course_node_type, 'Cue sheets and magic sheets', null, 2),
  ('d9bccb5d-f579-4998-93fb-e500221a1eec', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '2d23a482-137a-4edd-b53e-0aa2e39be189', 'subtopic'::public.curated_course_node_type, 'Lighting paperwork', 'Students learn professional documentation so a design can be hung, focused, programmed, and maintained.', 3),
  ('bbc08366-2726-4f13-9654-4563858b09b6', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'd9bccb5d-f579-4998-93fb-e500221a1eec', 'concept'::public.curated_course_node_type, 'Light plot', null, 0),
  ('4b997885-fce2-4894-895b-abb49d32a7e0', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'd9bccb5d-f579-4998-93fb-e500221a1eec', 'concept'::public.curated_course_node_type, 'Channel hookup', null, 1),
  ('c3b50057-7d3b-46d3-bff8-0f0e2b2ee7d2', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'd9bccb5d-f579-4998-93fb-e500221a1eec', 'concept'::public.curated_course_node_type, 'Focus notes and instrument schedule', null, 2),
  ('34f89064-35dd-4849-9a4c-600e22434f48', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Costume Design Fundamentals', 'Costume design places character, body, culture, and story in motion. Students learn to design clothing as action, identity, period, and performance technology.', 4),
  ('cdee6b1c-2890-4471-acb4-edce43811503', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '34f89064-35dd-4849-9a4c-600e22434f48', 'subtopic'::public.curated_course_node_type, 'Character, body, and silhouette', 'Students learn how clothing communicates status, transformation, age, labor, desire, and relationship before a character speaks.', 0),
  ('bf38619e-2351-4163-80da-f29e4aba2a6e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'cdee6b1c-2890-4471-acb4-edce43811503', 'concept'::public.curated_course_node_type, 'Silhouette and proportion', null, 0),
  ('df5a75f5-0d41-4f4e-bbf0-82485793818c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'cdee6b1c-2890-4471-acb4-edce43811503', 'concept'::public.curated_course_node_type, 'Actor movement and comfort', null, 1),
  ('680626b8-0464-404c-bb2c-e65d752be714', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'cdee6b1c-2890-4471-acb4-edce43811503', 'concept'::public.curated_course_node_type, 'Character arcs through dress', null, 2),
  ('f663c028-f771-4660-8c0c-8561fb598cfd', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '34f89064-35dd-4849-9a4c-600e22434f48', 'subtopic'::public.curated_course_node_type, 'Period and cultural research', 'The aim is accuracy with interpretation. Students practice respectful, specific research rather than generic historical or cultural shorthand.', 1),
  ('7faedf4f-41fa-4c75-bba0-10cdbd5315ce', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f663c028-f771-4660-8c0c-8561fb598cfd', 'concept'::public.curated_course_node_type, 'Historic clothing systems', null, 0),
  ('7d8391dd-9330-4c13-a015-0e641bb0e46d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f663c028-f771-4660-8c0c-8561fb598cfd', 'concept'::public.curated_course_node_type, 'Cultural context and consultation', null, 1),
  ('41224bfb-e614-413f-b1c6-a54905de1884', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f663c028-f771-4660-8c0c-8561fb598cfd', 'concept'::public.curated_course_node_type, 'Avoiding stereotype and costume cliche', null, 2),
  ('7ad66d45-9dbd-4b84-9136-62cfef3eb421', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '34f89064-35dd-4849-9a4c-600e22434f48', 'subtopic'::public.curated_course_node_type, 'Textiles, color, and construction logic', 'Students connect image to physical reality: fabric behavior, quick changes, maintenance, and shop feasibility.', 2),
  ('e18e8cfa-c239-4be5-b033-94c7c4fafa73', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7ad66d45-9dbd-4b84-9136-62cfef3eb421', 'concept'::public.curated_course_node_type, 'Fabric drape and texture', null, 0),
  ('30b55cfd-ddc2-4759-b852-bc8ba255e69e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7ad66d45-9dbd-4b84-9136-62cfef3eb421', 'concept'::public.curated_course_node_type, 'Palette and symbolism', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3d398ba4-995c-4c22-b5bd-e3809727fec8', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7ad66d45-9dbd-4b84-9136-62cfef3eb421', 'concept'::public.curated_course_node_type, 'Build, pull, rent, or buy decisions', null, 2),
  ('9fcf3572-8faa-4f8f-a50c-6f35aca3e571', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '34f89064-35dd-4849-9a4c-600e22434f48', 'subtopic'::public.curated_course_node_type, 'Costume rendering and communication', 'The point is to make character choices legible to directors, actors, drapers, and shops.', 3),
  ('6021ee75-2e21-4c28-8e7e-23c19c568885', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9fcf3572-8faa-4f8f-a50c-6f35aca3e571', 'concept'::public.curated_course_node_type, 'Figure drawing basics', null, 0),
  ('e273a61d-848f-44fe-a450-ff14e8f06847', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9fcf3572-8faa-4f8f-a50c-6f35aca3e571', 'concept'::public.curated_course_node_type, 'Swatches and research plates', null, 1),
  ('c8132bbc-7717-4279-a277-00f9adb86827', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9fcf3572-8faa-4f8f-a50c-6f35aca3e571', 'concept'::public.curated_course_node_type, 'Costume plots and change charts', null, 2),
  ('7280365c-e041-43f1-b1f9-f1d91450eed0', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Sound Design Fundamentals', 'Sound design builds atmosphere, rhythm, memory, place, and emotional pressure. Students learn to listen dramaturgically and design a sonic world.', 5),
  ('a2a85860-13fa-4832-89df-4bbc4ec7632c', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7280365c-e041-43f1-b1f9-f1d91450eed0', 'subtopic'::public.curated_course_node_type, 'Sonic dramaturgy', 'Students learn why sound belongs in the design conversation from the beginning, not only as an effect added late.', 0),
  ('e33f0d36-1fb2-41dc-bfd2-c7d7c1038a92', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a2a85860-13fa-4832-89df-4bbc4ec7632c', 'concept'::public.curated_course_node_type, 'Motifs and recurring sounds', null, 0),
  ('e9acebd2-91b6-42cf-aa54-5c554e0cf31f', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a2a85860-13fa-4832-89df-4bbc4ec7632c', 'concept'::public.curated_course_node_type, 'Silence as a design choice', null, 1),
  ('8ee3f0ba-1fab-432f-869a-9ad4b742ed4a', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a2a85860-13fa-4832-89df-4bbc4ec7632c', 'concept'::public.curated_course_node_type, 'Point of view and memory', null, 2),
  ('f377d82d-7a69-4c66-a5eb-b8c41341be2b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7280365c-e041-43f1-b1f9-f1d91450eed0', 'subtopic'::public.curated_course_node_type, 'Music, effects, and ambience', 'The goal is to distinguish categories of sound and understand how each affects storytelling.', 1),
  ('cb7f03c2-6c65-4b2e-8646-eedfb3c6d0ee', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f377d82d-7a69-4c66-a5eb-b8c41341be2b', 'concept'::public.curated_course_node_type, 'Diegetic and non-diegetic sound', null, 0),
  ('f06088e6-9bf5-4497-a7d4-b4340f3539dd', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f377d82d-7a69-4c66-a5eb-b8c41341be2b', 'concept'::public.curated_course_node_type, 'Transitions and underscoring', null, 1),
  ('cc810da5-66ec-4bab-99f1-f9cdc0892e90', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'f377d82d-7a69-4c66-a5eb-b8c41341be2b', 'concept'::public.curated_course_node_type, 'Environmental beds', null, 2),
  ('e49b9ed2-75f4-403b-a55f-0333a6a92557', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7280365c-e041-43f1-b1f9-f1d91450eed0', 'subtopic'::public.curated_course_node_type, 'Systems and playback basics', 'Students learn enough technical vocabulary to collaborate with engineers and make practical choices.', 2),
  ('15e6a8e2-2b54-4a1c-bd1a-6ee53dafdc55', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e49b9ed2-75f4-403b-a55f-0333a6a92557', 'concept'::public.curated_course_node_type, 'Speakers and coverage', null, 0),
  ('e2c61c4f-7647-4703-a204-b9496e827813', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e49b9ed2-75f4-403b-a55f-0333a6a92557', 'concept'::public.curated_course_node_type, 'Microphones and reinforcement', null, 1),
  ('932a79c3-9365-44a6-a2bb-cfe48f9e9fde', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'e49b9ed2-75f4-403b-a55f-0333a6a92557', 'concept'::public.curated_course_node_type, 'Playback software and cue stacks', null, 2),
  ('0892b379-6065-4847-961a-c78d34d6abdb', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '7280365c-e041-43f1-b1f9-f1d91450eed0', 'subtopic'::public.curated_course_node_type, 'Cue documentation', 'Sound choices must be repeatable. Students practice cue sheets, source logs, and rehearsal notes.', 3),
  ('60fe3287-d66c-46e0-bac4-9c0e4173b08b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '0892b379-6065-4847-961a-c78d34d6abdb', 'concept'::public.curated_course_node_type, 'Cue lists', null, 0),
  ('458aa849-9d7a-4fbb-9939-020c03231f40', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '0892b379-6065-4847-961a-c78d34d6abdb', 'concept'::public.curated_course_node_type, 'Copyright and licensing notes', null, 1),
  ('ead36e93-5387-49b7-9ded-c7c113e6537b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '0892b379-6065-4847-961a-c78d34d6abdb', 'concept'::public.curated_course_node_type, 'Tech rehearsal updates', null, 2),
  ('5e192ad3-619d-43cb-82e8-a0c48faa3b8b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Rendering and Presentation', 'Presentation is how a design becomes shareable. Students learn visual and verbal methods for persuading collaborators and making choices clear.', 6),
  ('bffe0040-fd73-43e4-b6b6-450e0e3d3774', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5e192ad3-619d-43cb-82e8-a0c48faa3b8b', 'subtopic'::public.curated_course_node_type, 'Drawing, drafting, and model-making', 'Students learn multiple ways to represent scale, mood, detail, and spatial relationships.', 0),
  ('c525faa5-d132-4055-8001-e869547921f1', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'bffe0040-fd73-43e4-b6b6-450e0e3d3774', 'concept'::public.curated_course_node_type, 'Sketching and thumbnails', null, 0),
  ('0d19173c-8314-4d45-ba92-cb9e36efc423', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'bffe0040-fd73-43e4-b6b6-450e0e3d3774', 'concept'::public.curated_course_node_type, 'Orthographic drafting', null, 1),
  ('5577a425-2013-43c2-9a4f-7fca28680da2', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'bffe0040-fd73-43e4-b6b6-450e0e3d3774', 'concept'::public.curated_course_node_type, 'Physical and digital models', null, 2),
  ('35201cfd-de0b-4efc-a404-68f4be5fe256', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5e192ad3-619d-43cb-82e8-a0c48faa3b8b', 'subtopic'::public.curated_course_node_type, 'Mood boards and visual research boards', 'The point is to curate evidence so the production team can see the proposed world and its rules.', 1),
  ('0c28e093-eb1f-4044-8e1f-f8f8429fd508', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '35201cfd-de0b-4efc-a404-68f4be5fe256', 'concept'::public.curated_course_node_type, 'Image selection', null, 0),
  ('af0b4dfc-f4f3-4c57-bac8-de6e35501db1', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '35201cfd-de0b-4efc-a404-68f4be5fe256', 'concept'::public.curated_course_node_type, 'Palette and texture boards', null, 1),
  ('7c599a5d-bc24-4747-b68b-77c1438e2e45', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '35201cfd-de0b-4efc-a404-68f4be5fe256', 'concept'::public.curated_course_node_type, 'Source labeling and research ethics', null, 2),
  ('5944251e-9681-4fae-b391-bdb847138037', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5e192ad3-619d-43cb-82e8-a0c48faa3b8b', 'subtopic'::public.curated_course_node_type, 'Digital visualization', 'Students practice contemporary tools while keeping design thinking ahead of software technique.', 2),
  ('c8eb4b6f-b063-4ba3-baf6-e42c30b6cc90', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5944251e-9681-4fae-b391-bdb847138037', 'concept'::public.curated_course_node_type, 'Vector and raster workflows', null, 0),
  ('069790d6-3cd3-4b58-8d9e-294bc998f58b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5944251e-9681-4fae-b391-bdb847138037', 'concept'::public.curated_course_node_type, '3D massing and rendering', null, 1),
  ('d413b275-67f3-4bae-9e93-8b510ac8706b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5944251e-9681-4fae-b391-bdb847138037', 'concept'::public.curated_course_node_type, 'Projection and media mockups', null, 2),
  ('61a4bb12-226b-4197-a735-8d47a882ac78', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5e192ad3-619d-43cb-82e8-a0c48faa3b8b', 'subtopic'::public.curated_course_node_type, 'Critique and presentation language', 'Designers must explain choices without over-defending them. Students learn concise, specific, collaborative presentation habits.', 3),
  ('3e06835e-443d-4035-b9aa-64fa74057649', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '61a4bb12-226b-4197-a735-8d47a882ac78', 'concept'::public.curated_course_node_type, 'Design statements', null, 0),
  ('81e30f09-9ae3-4c0e-9363-7e612cccf26d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '61a4bb12-226b-4197-a735-8d47a882ac78', 'concept'::public.curated_course_node_type, 'Responding to notes', null, 1),
  ('81e74bb1-c2f6-400e-8c91-ca1242fbfafc', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '61a4bb12-226b-4197-a735-8d47a882ac78', 'concept'::public.curated_course_node_type, 'Portfolio-ready documentation', null, 2),
  ('76367919-0c9b-4d36-859d-7e2ebfccd8c8', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Collaboration with the Director', 'Theater design is collaborative authorship. Students learn how to align strong design ideas with a director''s staging, actor process, dramaturgy, and production reality.', 7);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('67053643-e25f-4021-80ef-f16e1593eb35', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '76367919-0c9b-4d36-859d-7e2ebfccd8c8', 'subtopic'::public.curated_course_node_type, 'Director-designer conversations', 'Students learn to ask useful questions, listen for priorities, and translate abstract goals into concrete design paths.', 0),
  ('ddafdc42-eb95-45d1-806a-c4159b6d0af6', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '67053643-e25f-4021-80ef-f16e1593eb35', 'concept'::public.curated_course_node_type, 'Initial meeting prompts', null, 0),
