  ('5c07d578-9487-4166-952f-dce2a9f39320', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '02b49d16-33a2-4c19-bdae-1d3e4bdbabc7', 'concept'::public.curated_course_node_type, 'Interdepartmental dependencies', null, 2),
  ('5fc47291-7970-4b68-a601-a8ff13b02c4a', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '76367919-0c9b-4d36-859d-7e2ebfccd8c8', 'subtopic'::public.curated_course_node_type, 'Negotiation and feedback', 'Students learn that notes are part of craft. They practice preserving design intent while solving real production problems.', 2),
