  ('737ebef8-8caf-43a2-835e-aabf1bdf581d', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '76367919-0c9b-4d36-859d-7e2ebfccd8c8', 'subtopic'::public.curated_course_node_type, 'Dramaturgical responsibility', 'Design collaboration includes ethical and cultural accountability for what appears on stage.', 3),
  ('850e9081-e2c5-4084-b6dc-dae8a5ff5541', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '737ebef8-8caf-43a2-835e-aabf1bdf581d', 'concept'::public.curated_course_node_type, 'Representation and harm reduction', null, 0),
  ('e19c3d4e-0e41-4216-a859-f7b9e28d099b', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '737ebef8-8caf-43a2-835e-aabf1bdf581d', 'concept'::public.curated_course_node_type, 'Consultants and community knowledge', null, 1),
  ('88fcee4c-c313-4471-b680-a31fe25aabde', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '737ebef8-8caf-43a2-835e-aabf1bdf581d', 'concept'::public.curated_course_node_type, 'Audience context', null, 2),
  ('ac81455a-0ac5-4d4c-8e56-ce46485039a6', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Design for Different Spaces', 'A design changes when the audience relationship changes. Students learn to adapt theatrical ideas to architecture, scale, proximity, mobility, technology, and access.', 8),
  ('5b83ff41-99b0-4d51-91a7-ea11c59f4e58', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'ac81455a-0ac5-4d4c-8e56-ce46485039a6', 'subtopic'::public.curated_course_node_type, 'Stage configurations', 'Students compare how proscenium, thrust, arena, and black box spaces shape composition and actor-audience relationships.', 0),
  ('eaa0143f-5430-47ec-8714-ce49846de834', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5b83ff41-99b0-4d51-91a7-ea11c59f4e58', 'concept'::public.curated_course_node_type, 'Sightlines', null, 0),
  ('5c42aa95-b97d-4c02-b7d3-b2bf75ae387e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5b83ff41-99b0-4d51-91a7-ea11c59f4e58', 'concept'::public.curated_course_node_type, 'Entrances and circulation', null, 1),
  ('5f67ddce-bd10-45ee-bc4e-502130f81247', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '5b83ff41-99b0-4d51-91a7-ea11c59f4e58', 'concept'::public.curated_course_node_type, 'Backstage and storage limits', null, 2),
  ('59215e5f-665d-474a-9b47-afeffd8b1e62', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'ac81455a-0ac5-4d4c-8e56-ce46485039a6', 'subtopic'::public.curated_course_node_type, 'Site-specific and immersive design', 'The goal is to treat location as a co-author rather than a neutral container.', 1),
  ('db364e36-c69c-456c-9da1-565741e46bdb', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '59215e5f-665d-474a-9b47-afeffd8b1e62', 'concept'::public.curated_course_node_type, 'Audience pathway', null, 0),
  ('ad55c28d-cac8-4549-93ad-f4873dc81f61', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '59215e5f-665d-474a-9b47-afeffd8b1e62', 'concept'::public.curated_course_node_type, 'Environmental storytelling', null, 1),
  ('5d17f2b9-1cb9-4483-8ea1-942ef2689426', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '59215e5f-665d-474a-9b47-afeffd8b1e62', 'concept'::public.curated_course_node_type, 'Permissions, safety, and weather', null, 2),
  ('a644700f-9a17-4cb0-841f-725111223043', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'ac81455a-0ac5-4d4c-8e56-ce46485039a6', 'subtopic'::public.curated_course_node_type, 'Touring and resource-limited design', 'Students learn how constraints can sharpen invention while preserving the production''s essential design idea.', 2),
  ('898db6c8-a3a7-474f-aa48-32f13b295ef4', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a644700f-9a17-4cb0-841f-725111223043', 'concept'::public.curated_course_node_type, 'Portability and packing', null, 0),
  ('6635d6ef-8b9d-4bd1-8c8e-3eec45abff0e', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a644700f-9a17-4cb0-841f-725111223043', 'concept'::public.curated_course_node_type, 'Modular scenery', null, 1),
  ('89bb5f41-fa01-4f57-ae17-b4ecc9e8d7db', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'a644700f-9a17-4cb0-841f-725111223043', 'concept'::public.curated_course_node_type, 'Local labor and venue adaptation', null, 2),
  ('9534e720-59d7-4eb2-ba08-0e61fbecc2c0', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'ac81455a-0ac5-4d4c-8e56-ce46485039a6', 'subtopic'::public.curated_course_node_type, 'Accessibility and inclusive experience', 'Design must consider who can enter, perceive, and participate in the event.', 3),
  ('9e9b8fb9-8fd7-4f0f-911b-19197c413cfd', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9534e720-59d7-4eb2-ba08-0e61fbecc2c0', 'concept'::public.curated_course_node_type, 'Accessible routes and seating', null, 0),
  ('5c754edb-ba83-480b-8265-510de22fc9ac', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9534e720-59d7-4eb2-ba08-0e61fbecc2c0', 'concept'::public.curated_course_node_type, 'Captioning and audio description interfaces', null, 1),
  ('c2f43bf1-94df-4d26-b21d-4147f33e6994', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '9534e720-59d7-4eb2-ba08-0e61fbecc2c0', 'concept'::public.curated_course_node_type, 'Sensory considerations', null, 2),
  ('af8d4117-28eb-412c-afeb-3455c4342f76', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', null, 'topic'::public.curated_course_node_type, 'Realizing a Design', 'Realization is where design meets shops, crews, time, money, safety, and audiences. Students learn how artistic choices become repeatable production practice.', 9),
  ('83abc25a-ebc2-4581-aadb-4bb60cd44dfa', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'af8d4117-28eb-412c-afeb-3455c4342f76', 'subtopic'::public.curated_course_node_type, 'Budgets, calendars, and build planning', 'Students learn to make creative decisions with practical consequences visible early.', 0),
  ('16cd7a6b-f867-4fb8-bf48-87349a12a9e2', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '83abc25a-ebc2-4581-aadb-4bb60cd44dfa', 'concept'::public.curated_course_node_type, 'Cost estimates', null, 0),
  ('2282a14c-3385-4b4d-8461-d7aa610ecbc0', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '83abc25a-ebc2-4581-aadb-4bb60cd44dfa', 'concept'::public.curated_course_node_type, 'Build schedules', null, 1),
  ('d3fbcb7d-930a-4752-89cb-fd3b166f44f4', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', '83abc25a-ebc2-4581-aadb-4bb60cd44dfa', 'concept'::public.curated_course_node_type, 'Rental, purchase, and fabrication choices', null, 2),
  ('d8260764-bea1-407d-886c-ac5b31e9c9a4', 'c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'af8d4117-28eb-412c-afeb-3455c4342f76', 'subtopic'::public.curated_course_node_type, 'Shop collaboration and technical direction', 'The point is to respect the expertise of makers and technicians while keeping the design''s intent clear.', 1),
