delete from public.curated_courses where slug = 'design-for-the-theater';

values ('c5d6e7f8-9a0b-4c25-8e45-5f6a7b8c9d25', 'design-for-the-theater', 'Design for the Theater', 'Design for the Theater is an upper-division undergraduate course that introduces students to the artistic, analytical, and practical foundations of theatrical design. The course treats design as dramaturgy in visible, spatial, material, sonic, and temporal form. Students study scenic, lighting, costume, and sound design while learning how designers collaborate with directors, performers, dramaturgs, stage managers, shops, and production teams. Students are trained to read plays visually and sonically, research with cultural care, communicate through drawings and models, critique design choices, understand production constraints, and document work for future creative development.');

