select
  'design-for-the-theater',
  null,
  'Design for the Theater',
  'Design for the Theater',
  'Design for the Theater is an upper-division undergraduate course that introduces students to the artistic, analytical, and practical foundations of theatrical design. The course treats design as dramaturgy in visible, spatial, material, sonic, and temporal form. Students study scenic, lighting, costume, and sound design while learning how designers collaborate with directors, performers, dramaturgs, stage managers, shops, and production teams. Students are trained to read plays visually and sonically, research with cultural care, communicate through drawings and models, critique design choices, understand production constraints, and document work for future creative development.',
  $dthtjson${"slug": "design-for-the-theater", "title": "Design for the Theater", "description": "Design for the Theater is an upper-division undergraduate course that introduces students to the artistic, analytical, and practical foundations of theatrical design. The course treats design as dramaturgy in visible, spatial, material, sonic, and temporal form. Students study scenic, lighting, costume, and sound design while learning how designers collaborate with directors, performers, dramaturgs, stage managers, shops, and production teams. Students are trained to read plays visually and sonically, research with cultural care, communicate through drawings and models, critique design choices, understand production constraints, and document work for future creative development.", "topics": [{"id": "62045ea4-d9a5-498b-aaa0-806778b442bf", "type": "topic", "title": "The Design Process", "description": "This section teaches design as a disciplined creative cycle. Students learn how an initial response to a script becomes a tested, communicable, buildable design proposal.", "children": [{"id": "e0eb5007-d489-47b6-be46-da5e9e7d6d7c", "type": "subtopic", "title": "First response and design questions", "children": [{"id": "d35d0b46-cdce-489f-9a43-3188e25c4a6d", "type": "concept", "title": "Image and emotional response"}, {"id": "1b61a5bf-eae6-453b-8cec-5c537fe2221f", "type": "concept", "title": "Questions for director and dramaturg"}, {"id": "721e463e-d8f5-4e28-8542-3eb024861dbe", "type": "concept", "title": "Early constraints and opportunities"}], "description": "The point is to capture instinct before analysis flattens it. Designers learn to name curiosity, discomfort, attraction, and the questions that will guide research."}, {"id": "33e817c4-b3a1-490b-9b89-03130b73832d", "type": "subtopic", "title": "Research and dramaturgical inquiry", "children": [{"id": "cbede6fd-ed48-4136-943f-fda87f2a1c7e", "type": "concept", "title": "Primary and secondary sources"}, {"id": "b8f50494-ef19-4d64-abe2-f5751afd6c9b", "type": "concept", "title": "Visual culture and period research"}, {"id": "709dc874-307a-4f49-a190-51dff46ecd30", "type": "concept", "title": "Cultural specificity and ethical research"}], "description": "Research gives the design a world beyond taste. Students learn to gather visual, historical, cultural, material, and sensory evidence."}, {"id": "f4701020-6943-449f-b3e8-bbeda3c091e4", "type": "subtopic", "title": "Concept development", "children": [{"id": "3820d976-ade0-4757-abb4-8b70dd33b38e", "type": "concept", "title": "Metaphor and organizing image"}, {"id": "5622b615-9e2c-48b4-9465-14e939ef6024", "type": "concept", "title": "Style, tone, and theatrical rules"}, {"id": "6be9667e-591b-4f10-b071-d1f0958f9218", "type": "concept", "title": "Concept statements and design vocabulary"}], "description": "Concept turns research into a clear design argument. Students practice moving from many references to one coherent production idea."}, {"id": "e720c304-7234-4a88-b295-40eb74be8676", "type": "subtopic", "title": "Iteration and critique", "children": [{"id": "bf48e50a-c310-4f46-a064-1afac0253f4e", "type": "concept", "title": "Thumbnail studies"}, {"id": "ca03af6f-d3a3-4905-b2c1-70c2785e888e", "type": "concept", "title": "Peer critique protocols"}, {"id": "04ad077f-c725-4878-a2e5-6902b5ab22df", "type": "concept", "title": "Revision logs and decision rationale"}], "description": "Design improves through revision. Students learn to test choices, receive critique, and refine without losing the core idea."}]}, {"id": "5cea4df6-7563-4938-8d45-622b65f96c28", "type": "topic", "title": "Script Analysis for Designers", "description": "Designers read scripts for visible and invisible demands: space, time, action, atmosphere, bodies, sound, objects, and transformation.", "children": [{"id": "4bdaaaac-5228-421d-bcb1-8139ce0dab08", "type": "subtopic", "title": "Given circumstances and world of the play", "children": [{"id": "c481b38b-1630-4abd-8097-dea20369b5fb", "type": "concept", "title": "Place and period"}, {"id": "d0580d9e-8afd-488c-bb1a-546ffc47c28c", "type": "concept", "title": "Social class and institutions"}, {"id": "23681f53-5284-45db-be7d-508f53b04f08", "type": "concept", "title": "Weather, season, and time"}], "description": "Students learn to identify the facts that every design must honor or intentionally transform."}, {"id": "32e7c738-8df3-4bef-b441-1af8f47bb6cc", "type": "subtopic", "title": "Dramatic action and structure", "children": [{"id": "c32dd2d1-d5b1-4c45-92dc-afb3bbd8e45d", "type": "concept", "title": "Events and turning points"}, {"id": "0c608bb4-4123-4e87-b398-3c50a8186d9e", "type": "concept", "title": "Beats and tempo"}, {"id": "2268e287-f22c-48dc-b942-29f095e2735f", "type": "concept", "title": "Scene transitions"}], "description": "The goal is to understand how design supports conflict, change, and rhythm rather than decorating scenes."}, {"id": "95631db5-3ef3-425f-ac08-14d262328188", "type": "subtopic", "title": "Character and social identity", "children": [{"id": "123d7fc8-11be-48a8-8e6a-fb6a3c41b388", "type": "concept", "title": "Character research"}, {"id": "92b9c75d-94c4-4959-8970-99c17b014e44", "type": "concept", "title": "Costume and object biographies"}, {"id": "506ec214-528d-4be1-915b-52236e590b61", "type": "concept", "title": "Power, identity, and representation"}], "description": "Design choices reveal how characters move through status, desire, labor, culture, and community."}, {"id": "2add15fd-8c4c-4caa-9bdb-5ef4405db0b2", "type": "subtopic", "title": "Designable moments", "children": [{"id": "3171759a-7381-4244-b46b-3d3eade4e546", "type": "concept", "title": "Entrances and exits"}, {"id": "ef9f5d35-2a45-45d8-918f-507263835f8b", "type": "concept", "title": "Reveals and transformations"}, {"id": "46f00e40-db20-43c1-bdf2-089fe99b97fe", "type": "concept", "title": "Silence, darkness, and sonic shifts"}], "description": "Students identify where scenery, light, costume, sound, and props can actively tell the story."}]}, {"id": "b97da1ff-78ac-49af-9d5d-3b480d903a58", "type": "topic", "title": "Scenic Design Fundamentals", "description": "Scenic design gives the production a spatial argument. Students learn how scale, architecture, texture, line, and movement shape the audience's reading of the play.", "children": [{"id": "e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4", "type": "subtopic", "title": "Stage space and composition", "children": [{"id": "adeb06fa-dad8-4650-805b-a4855c95f637", "type": "concept", "title": "Proportion and balance"}, {"id": "e8ff1870-8465-4b29-8029-ecd648b2fd88", "type": "concept", "title": "Sightlines and focus"}, {"id": "b1fa1bc8-3ee5-43ec-b637-142709326a37", "type": "concept", "title": "Positive and negative space"}], "description": "Students learn how the audience reads space and how a set can organize attention, status, and action."}, {"id": "9e0282ab-c0f9-404d-93cc-ea223c834285", "type": "subtopic", "title": "Ground plans and models", "children": [{"id": "b9105237-a148-4c29-9ea0-76a29fb2d448", "type": "concept", "title": "Scale and measurement"}, {"id": "e4c1f1ac-cd35-40c6-bd9d-d0c2f57c24ca", "type": "concept", "title": "Traffic and blocking"}, {"id": "d9cffab3-e6dc-4afc-a0b0-49945f674148", "type": "concept", "title": "White models and presentation models"}], "description": "The point is to make ideas testable. Students translate imagination into scaled documents that directors, actors, and shops can use."}, {"id": "a612d6bc-e473-4d3e-8c43-b4e45e649b8f", "type": "subtopic", "title": "Materials, texture, and color", "children": [{"id": "6c1c7521-93d8-4dcc-aac4-a2c740c63ede", "type": "concept", "title": "Paint treatments"}, {"id": "47171746-382d-4a31-a5aa-8ea62655bcb2", "type": "concept", "title": "Fabrication materials"}, {"id": "943e0b1f-40cd-4305-8258-b42fedca1c5e", "type": "concept", "title": "Palette and visual metaphor"}], "description": "Scenic surfaces carry meaning and practical consequences. Students connect aesthetic choices to budget, build, durability, and theatrical illusion."}, {"id": "b745b9e8-d874-4d97-9098-1c340d437941", "type": "subtopic", "title": "Scene shifts and stage mechanics", "children": [{"id": "817a7435-bdfe-4e47-87f0-7e52b006a35e", "type": "concept", "title": "Wagons, tracks, and turntables"}, {"id": "e7119e67-04d5-43d4-9759-6d8bd41c8601", "type": "concept", "title": "Flying and rigging basics"}, {"id": "9e9ded99-f4e9-45e2-97ca-b1301e75687a", "type": "concept", "title": "Crew choreography and safety"}], "description": "Design includes how the world changes. Students study transitions as part of storytelling, not just logistics."}]}, {"id": "2d23a482-137a-4edd-b53e-0aa2e39be189", "type": "topic", "title": "Lighting Design Fundamentals", "description": "Lighting makes the audience see, feel, and follow. Students learn how angle, color, intensity, time, and cue structure create the visual score of performance.", "children": [{"id": "6ba49b09-7827-4cf8-8638-87b215553b8c", "type": "subtopic", "title": "Functions of stage lighting", "children": [{"id": "8ab855e2-3472-43b9-9d38-17903089d7f3", "type": "concept", "title": "Visibility and selective focus"}, {"id": "3566beaf-712d-40af-9a73-66b29b7f8086", "type": "concept", "title": "Modeling bodies and space"}, {"id": "d4452ee9-c09d-44b7-8196-9bfcade9ba48", "type": "concept", "title": "Mood, style, and atmosphere"}], "description": "Students learn the practical and expressive purposes of light: visibility, focus, form, mood, rhythm, and environment."}, {"id": "afd3e397-75a4-44eb-83c8-256f0cf86665", "type": "subtopic", "title": "Color, angle, and instrument basics", "children": [{"id": "b50179e3-7ac6-4193-8389-2f42530b7c2d", "type": "concept", "title": "Fixture families"}, {"id": "f802da3e-ba78-45f2-875d-cedd862abb8d", "type": "concept", "title": "Hanging positions"}, {"id": "dbd517e2-70ba-4fc4-ae8c-3b7150c4db3c", "type": "concept", "title": "Gel, LED color, and color temperature"}], "description": "The point is to understand the tools before composing with them. Students connect equipment choices to visual effect."}, {"id": "52fcb0c2-6983-4ea0-8251-4fa0d88a87f7", "type": "subtopic", "title": "Cueing and time", "children": [{"id": "810adbec-c90f-4d34-8b1e-451833c71af3", "type": "concept", "title": "Cue structure"}, {"id": "75c33981-48e8-40e4-9297-d3001632a2ab", "type": "concept", "title": "Fades and blackouts"}, {"id": "ef89cf78-2988-4418-876e-8e10036c5a8e", "type": "concept", "title": "Cue sheets and magic sheets"}], "description": "Lighting design unfolds in time. Students practice making transitions that support dramatic rhythm and audience attention."}, {"id": "d9bccb5d-f579-4998-93fb-e500221a1eec", "type": "subtopic", "title": "Lighting paperwork", "children": [{"id": "bbc08366-2726-4f13-9654-4563858b09b6", "type": "concept", "title": "Light plot"}, {"id": "4b997885-fce2-4894-895b-abb49d32a7e0", "type": "concept", "title": "Channel hookup"}, {"id": "c3b50057-7d3b-46d3-bff8-0f0e2b2ee7d2", "type": "concept", "title": "Focus notes and instrument schedule"}], "description": "Students learn professional documentation so a design can be hung, focused, programmed, and maintained."}]}, {"id": "34f89064-35dd-4849-9a4c-600e22434f48", "type": "topic", "title": "Costume Design Fundamentals", "description": "Costume design places character, body, culture, and story in motion. Students learn to design clothing as action, identity, period, and performance technology.", "children": [{"id": "cdee6b1c-2890-4471-acb4-edce43811503", "type": "subtopic", "title": "Character, body, and silhouette", "children": [{"id": "bf38619e-2351-4163-80da-f29e4aba2a6e", "type": "concept", "title": "Silhouette and proportion"}, {"id": "df5a75f5-0d41-4f4e-bbf0-82485793818c", "type": "concept", "title": "Actor movement and comfort"}, {"id": "680626b8-0464-404c-bb2c-e65d752be714", "type": "concept", "title": "Character arcs through dress"}], "description": "Students learn how clothing communicates status, transformation, age, labor, desire, and relationship before a character speaks."}, {"id": "f663c028-f771-4660-8c0c-8561fb598cfd", "type": "subtopic", "title": "Period and cultural research", "children": [{"id": "7faedf4f-41fa-4c75-bba0-10cdbd5315ce", "type": "concept", "title": "Historic clothing systems"}, {"id": "7d8391dd-9330-4c13-a015-0e641bb0e46d", "type": "concept", "title": "Cultural context and consultation"}, {"id": "41224bfb-e614-413f-b1c6-a54905de1884", "type": "concept", "title": "Avoiding stereotype and costume cliche"}], "description": "The aim is accuracy with interpretation. Students practice respectful, specific research rather than generic historical or cultural shorthand."}, {"id": "7ad66d45-9dbd-4b84-9136-62cfef3eb421", "type": "subtopic", "title": "Textiles, color, and construction logic", "children": [{"id": "e18e8cfa-c239-4be5-b033-94c7c4fafa73", "type": "concept", "title": "Fabric drape and texture"}, {"id": "30b55cfd-ddc2-4759-b852-bc8ba255e69e", "type": "concept", "title": "Palette and symbolism"}, {"id": "3d398ba4-995c-4c22-b5bd-e3809727fec8", "type": "concept", "title": "Build, pull, rent, or buy decisions"}], "description": "Students connect image to physical reality: fabric behavior, quick changes, maintenance, and shop feasibility."}, {"id": "9fcf3572-8faa-4f8f-a50c-6f35aca3e571", "type": "subtopic", "title": "Costume rendering and communication", "children": [{"id": "6021ee75-2e21-4c28-8e7e-23c19c568885", "type": "concept", "title": "Figure drawing basics"}, {"id": "e273a61d-848f-44fe-a450-ff14e8f06847", "type": "concept", "title": "Swatches and research plates"}, {"id": "c8132bbc-7717-4279-a277-00f9adb86827", "type": "concept", "title": "Costume plots and change charts"}], "description": "The point is to make character choices legible to directors, actors, drapers, and shops."}]}, {"id": "7280365c-e041-43f1-b1f9-f1d91450eed0", "type": "topic", "title": "Sound Design Fundamentals", "description": "Sound design builds atmosphere, rhythm, memory, place, and emotional pressure. Students learn to listen dramaturgically and design a sonic world.", "children": [{"id": "a2a85860-13fa-4832-89df-4bbc4ec7632c", "type": "subtopic", "title": "Sonic dramaturgy", "children": [{"id": "e33f0d36-1fb2-41dc-bfd2-c7d7c1038a92", "type": "concept", "title": "Motifs and recurring sounds"}, {"id": "e9acebd2-91b6-42cf-aa54-5c554e0cf31f", "type": "concept", "title": "Silence as a design choice"}, {"id": "8ee3f0ba-1fab-432f-869a-9ad4b742ed4a", "type": "concept", "title": "Point of view and memory"}], "description": "Students learn why sound belongs in the design conversation from the beginning, not only as an effect added late."}, {"id": "f377d82d-7a69-4c66-a5eb-b8c41341be2b", "type": "subtopic", "title": "Music, effects, and ambience", "children": [{"id": "cb7f03c2-6c65-4b2e-8646-eedfb3c6d0ee", "type": "concept", "title": "Diegetic and non-diegetic sound"}, {"id": "f06088e6-9bf5-4497-a7d4-b4340f3539dd", "type": "concept", "title": "Transitions and underscoring"}, {"id": "cc810da5-66ec-4bab-99f1-f9cdc0892e90", "type": "concept", "title": "Environmental beds"}], "description": "The goal is to distinguish categories of sound and understand how each affects storytelling."}, {"id": "e49b9ed2-75f4-403b-a55f-0333a6a92557", "type": "subtopic", "title": "Systems and playback basics", "children": [{"id": "15e6a8e2-2b54-4a1c-bd1a-6ee53dafdc55", "type": "concept", "title": "Speakers and coverage"}, {"id": "e2c61c4f-7647-4703-a204-b9496e827813", "type": "concept", "title": "Microphones and reinforcement"}, {"id": "932a79c3-9365-44a6-a2bb-cfe48f9e9fde", "type": "concept", "title": "Playback software and cue stacks"}], "description": "Students learn enough technical vocabulary to collaborate with engineers and make practical choices."}, {"id": "0892b379-6065-4847-961a-c78d34d6abdb", "type": "subtopic", "title": "Cue documentation", "children": [{"id": "60fe3287-d66c-46e0-bac4-9c0e4173b08b", "type": "concept", "title": "Cue lists"}, {"id": "458aa849-9d7a-4fbb-9939-020c03231f40", "type": "concept", "title": "Copyright and licensing notes"}, {"id": "ead36e93-5387-49b7-9ded-c7c113e6537b", "type": "concept", "title": "Tech rehearsal updates"}], "description": "Sound choices must be repeatable. Students practice cue sheets, source logs, and rehearsal notes."}]}, {"id": "5e192ad3-619d-43cb-82e8-a0c48faa3b8b", "type": "topic", "title": "Rendering and Presentation", "description": "Presentation is how a design becomes shareable. Students learn visual and verbal methods for persuading collaborators and making choices clear.", "children": [{"id": "bffe0040-fd73-43e4-b6b6-450e0e3d3774", "type": "subtopic", "title": "Drawing, drafting, and model-making", "children": [{"id": "c525faa5-d132-4055-8001-e869547921f1", "type": "concept", "title": "Sketching and thumbnails"}, {"id": "0d19173c-8314-4d45-ba92-cb9e36efc423", "type": "concept", "title": "Orthographic drafting"}, {"id": "5577a425-2013-43c2-9a4f-7fca28680da2", "type": "concept", "title": "Physical and digital models"}], "description": "Students learn multiple ways to represent scale, mood, detail, and spatial relationships."}, {"id": "35201cfd-de0b-4efc-a404-68f4be5fe256", "type": "subtopic", "title": "Mood boards and visual research boards", "children": [{"id": "0c28e093-eb1f-4044-8e1f-f8f8429fd508", "type": "concept", "title": "Image selection"}, {"id": "af0b4dfc-f4f3-4c57-bac8-de6e35501db1", "type": "concept", "title": "Palette and texture boards"}, {"id": "7c599a5d-bc24-4747-b68b-77c1438e2e45", "type": "concept", "title": "Source labeling and research ethics"}], "description": "The point is to curate evidence so the production team can see the proposed world and its rules."}, {"id": "5944251e-9681-4fae-b391-bdb847138037", "type": "subtopic", "title": "Digital visualization", "children": [{"id": "c8eb4b6f-b063-4ba3-baf6-e42c30b6cc90", "type": "concept", "title": "Vector and raster workflows"}, {"id": "069790d6-3cd3-4b58-8d9e-294bc998f58b", "type": "concept", "title": "3D massing and rendering"}, {"id": "d413b275-67f3-4bae-9e93-8b510ac8706b", "type": "concept", "title": "Projection and media mockups"}], "description": "Students practice contemporary tools while keeping design thinking ahead of software technique."}, {"id": "61a4bb12-226b-4197-a735-8d47a882ac78", "type": "subtopic", "title": "Critique and presentation language", "children": [{"id": "3e06835e-443d-4035-b9aa-64fa74057649", "type": "concept", "title": "Design statements"}, {"id": "81e30f09-9ae3-4c0e-9363-7e612cccf26d", "type": "concept", "title": "Responding to notes"}, {"id": "81e74bb1-c2f6-400e-8c91-ca1242fbfafc", "type": "concept", "title": "Portfolio-ready documentation"}], "description": "Designers must explain choices without over-defending them. Students learn concise, specific, collaborative presentation habits."}]}, {"id": "76367919-0c9b-4d36-859d-7e2ebfccd8c8", "type": "topic", "title": "Collaboration with the Director", "description": "Theater design is collaborative authorship. Students learn how to align strong design ideas with a director's staging, actor process, dramaturgy, and production reality.", "children": [{"id": "67053643-e25f-4021-80ef-f16e1593eb35", "type": "subtopic", "title": "Director-designer conversations", "children": [{"id": "ddafdc42-eb95-45d1-806a-c4159b6d0af6", "type": "concept", "title": "Initial meeting prompts"}, {"id": "747763f1-037a-40a9-9ea3-42deec0eb8b6", "type": "concept", "title": "Shared vocabulary"}, {"id": "642a76d7-c14b-4d52-94ae-0dfe17137781", "type": "concept", "title": "Concept alignment"}], "description": "Students learn to ask useful questions, listen for priorities, and translate abstract goals into concrete design paths."}, {"id": "02b49d16-33a2-4c19-bdae-1d3e4bdbabc7", "type": "subtopic", "title": "Production meetings", "children": [{"id": "ef7465d8-554f-4860-9f64-cb84a16d359e", "type": "concept", "title": "Meeting reports"}, {"id": "5b71c406-d624-49ff-bfcc-dd0a8288bb68", "type": "concept", "title": "Open questions and action items"}, {"id": "5c07d578-9487-4166-952f-dce2a9f39320", "type": "concept", "title": "Interdepartmental dependencies"}], "description": "The point is to keep creative and technical decisions moving together across departments."}, {"id": "5fc47291-7970-4b68-a601-a8ff13b02c4a", "type": "subtopic", "title": "Negotiation and feedback", "children": [{"id": "2fcacd44-4cfe-49af-9c48-c8c50cab13a3", "type": "concept", "title": "Budget and schedule tradeoffs"}, {"id": "7f3b1501-3e21-4c43-bae8-77ca05897b54", "type": "concept", "title": "Actor and stage management needs"}, {"id": "eeea13d3-bef3-44be-aca7-69502c041afd", "type": "concept", "title": "Documenting revisions"}], "description": "Students learn that notes are part of craft. They practice preserving design intent while solving real production problems."}, {"id": "737ebef8-8caf-43a2-835e-aabf1bdf581d", "type": "subtopic", "title": "Dramaturgical responsibility", "children": [{"id": "850e9081-e2c5-4084-b6dc-dae8a5ff5541", "type": "concept", "title": "Representation and harm reduction"}, {"id": "e19c3d4e-0e41-4216-a859-f7b9e28d099b", "type": "concept", "title": "Consultants and community knowledge"}, {"id": "88fcee4c-c313-4471-b680-a31fe25aabde", "type": "concept", "title": "Audience context"}], "description": "Design collaboration includes ethical and cultural accountability for what appears on stage."}]}, {"id": "ac81455a-0ac5-4d4c-8e56-ce46485039a6", "type": "topic", "title": "Design for Different Spaces", "description": "A design changes when the audience relationship changes. Students learn to adapt theatrical ideas to architecture, scale, proximity, mobility, technology, and access.", "children": [{"id": "5b83ff41-99b0-4d51-91a7-ea11c59f4e58", "type": "subtopic", "title": "Stage configurations", "children": [{"id": "eaa0143f-5430-47ec-8714-ce49846de834", "type": "concept", "title": "Sightlines"}, {"id": "5c42aa95-b97d-4c02-b7d3-b2bf75ae387e", "type": "concept", "title": "Entrances and circulation"}, {"id": "5f67ddce-bd10-45ee-bc4e-502130f81247", "type": "concept", "title": "Backstage and storage limits"}], "description": "Students compare how proscenium, thrust, arena, and black box spaces shape composition and actor-audience relationships."}, {"id": "59215e5f-665d-474a-9b47-afeffd8b1e62", "type": "subtopic", "title": "Site-specific and immersive design", "children": [{"id": "db364e36-c69c-456c-9da1-565741e46bdb", "type": "concept", "title": "Audience pathway"}, {"id": "ad55c28d-cac8-4549-93ad-f4873dc81f61", "type": "concept", "title": "Environmental storytelling"}, {"id": "5d17f2b9-1cb9-4483-8ea1-942ef2689426", "type": "concept", "title": "Permissions, safety, and weather"}], "description": "The goal is to treat location as a co-author rather than a neutral container."}, {"id": "a644700f-9a17-4cb0-841f-725111223043", "type": "subtopic", "title": "Touring and resource-limited design", "children": [{"id": "898db6c8-a3a7-474f-aa48-32f13b295ef4", "type": "concept", "title": "Portability and packing"}, {"id": "6635d6ef-8b9d-4bd1-8c8e-3eec45abff0e", "type": "concept", "title": "Modular scenery"}, {"id": "89bb5f41-fa01-4f57-ae17-b4ecc9e8d7db", "type": "concept", "title": "Local labor and venue adaptation"}], "description": "Students learn how constraints can sharpen invention while preserving the production's essential design idea."}, {"id": "9534e720-59d7-4eb2-ba08-0e61fbecc2c0", "type": "subtopic", "title": "Accessibility and inclusive experience", "children": [{"id": "9e9b8fb9-8fd7-4f0f-911b-19197c413cfd", "type": "concept", "title": "Accessible routes and seating"}, {"id": "5c754edb-ba83-480b-8265-510de22fc9ac", "type": "concept", "title": "Captioning and audio description interfaces"}, {"id": "c2f43bf1-94df-4d26-b21d-4147f33e6994", "type": "concept", "title": "Sensory considerations"}], "description": "Design must consider who can enter, perceive, and participate in the event."}]}, {"id": "af8d4117-28eb-412c-afeb-3455c4342f76", "type": "topic", "title": "Realizing a Design", "description": "Realization is where design meets shops, crews, time, money, safety, and audiences. Students learn how artistic choices become repeatable production practice.", "children": [{"id": "83abc25a-ebc2-4581-aadb-4bb60cd44dfa", "type": "subtopic", "title": "Budgets, calendars, and build planning", "children": [{"id": "16cd7a6b-f867-4fb8-bf48-87349a12a9e2", "type": "concept", "title": "Cost estimates"}, {"id": "2282a14c-3385-4b4d-8461-d7aa610ecbc0", "type": "concept", "title": "Build schedules"}, {"id": "d3fbcb7d-930a-4752-89cb-fd3b166f44f4", "type": "concept", "title": "Rental, purchase, and fabrication choices"}], "description": "Students learn to make creative decisions with practical consequences visible early."}, {"id": "d8260764-bea1-407d-886c-ac5b31e9c9a4", "type": "subtopic", "title": "Shop collaboration and technical direction", "children": [{"id": "fcd38624-d17c-474a-8425-780e4467b8d3", "type": "concept", "title": "Drafting handoff"}, {"id": "c9d5b0da-d984-4d91-928d-4dbb0e77be83", "type": "concept", "title": "Material tests"}, {"id": "8021f420-78ae-4b7f-b02b-41b3fa518dc3", "type": "concept", "title": "Technical problem solving"}], "description": "The point is to respect the expertise of makers and technicians while keeping the design's intent clear."}, {"id": "e4e71611-37aa-4235-8637-f969f08caa9e", "type": "subtopic", "title": "Tech rehearsal and previews", "children": [{"id": "4c5c352b-767e-46bf-87a6-fc92cead8727", "type": "concept", "title": "Cue-to-cue"}, {"id": "1c5db6c1-3bfc-4702-bfcc-0fe78147aef1", "type": "concept", "title": "Dress rehearsal notes"}, {"id": "027be96e-db52-4b1b-a752-b02cd5947667", "type": "concept", "title": "Prioritizing fixes"}], "description": "Students learn how designs change under live conditions and how to take notes productively."}, {"id": "757fd7e1-9a85-4835-b5a0-664c924e4ce9", "type": "subtopic", "title": "Safety, sustainability, and professional practice", "children": [{"id": "1509a12f-3baf-4f6a-92d4-5c740ac3951b", "type": "concept", "title": "Rigging and electrical safety awareness"}, {"id": "f054cea2-afe3-461f-b6bf-bb42be61cf48", "type": "concept", "title": "Sustainable materials and reuse"}, {"id": "0296c4e4-7012-48a3-a121-981d9221d5dc", "type": "concept", "title": "Portfolio reflection and archival documentation"}], "description": "Design includes care for workers, performers, materials, and communities."}]}], "dbBacked": true}$dthtjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'design-for-the-theater'
);

update public.learning_paths
set
  title = 'Design for the Theater',
  goal = 'Design for the Theater',
  summary = 'Design for the Theater is an upper-division undergraduate course that introduces students to the artistic, analytical, and practical foundations of theatrical design. The course treats design as dramaturgy in visible, spatial, material, sonic, and temporal form. Students study scenic, lighting, costume, and sound design while learning how designers collaborate with directors, performers, dramaturgs, stage managers, shops, and production teams. Students are trained to read plays visually and sonically, research with cultural care, communicate through drawings and models, critique design choices, understand production constraints, and document work for future creative development.',
  data = $dthtjson${"slug": "design-for-the-theater", "title": "Design for the Theater", "description": "Design for the Theater is an upper-division undergraduate course that introduces students to the artistic, analytical, and practical foundations of theatrical design. The course treats design as dramaturgy in visible, spatial, material, sonic, and temporal form. Students study scenic, lighting, costume, and sound design while learning how designers collaborate with directors, performers, dramaturgs, stage managers, shops, and production teams. Students are trained to read plays visually and sonically, research with cultural care, communicate through drawings and models, critique design choices, understand production constraints, and document work for future creative development.", "topics": [{"id": "62045ea4-d9a5-498b-aaa0-806778b442bf", "type": "topic", "title": "The Design Process", "description": "This section teaches design as a disciplined creative cycle. Students learn how an initial response to a script becomes a tested, communicable, buildable design proposal.", "children": [{"id": "e0eb5007-d489-47b6-be46-da5e9e7d6d7c", "type": "subtopic", "title": "First response and design questions", "children": [{"id": "d35d0b46-cdce-489f-9a43-3188e25c4a6d", "type": "concept", "title": "Image and emotional response"}, {"id": "1b61a5bf-eae6-453b-8cec-5c537fe2221f", "type": "concept", "title": "Questions for director and dramaturg"}, {"id": "721e463e-d8f5-4e28-8542-3eb024861dbe", "type": "concept", "title": "Early constraints and opportunities"}], "description": "The point is to capture instinct before analysis flattens it. Designers learn to name curiosity, discomfort, attraction, and the questions that will guide research."}, {"id": "33e817c4-b3a1-490b-9b89-03130b73832d", "type": "subtopic", "title": "Research and dramaturgical inquiry", "children": [{"id": "cbede6fd-ed48-4136-943f-fda87f2a1c7e", "type": "concept", "title": "Primary and secondary sources"}, {"id": "b8f50494-ef19-4d64-abe2-f5751afd6c9b", "type": "concept", "title": "Visual culture and period research"}, {"id": "709dc874-307a-4f49-a190-51dff46ecd30", "type": "concept", "title": "Cultural specificity and ethical research"}], "description": "Research gives the design a world beyond taste. Students learn to gather visual, historical, cultural, material, and sensory evidence."}, {"id": "f4701020-6943-449f-b3e8-bbeda3c091e4", "type": "subtopic", "title": "Concept development", "children": [{"id": "3820d976-ade0-4757-abb4-8b70dd33b38e", "type": "concept", "title": "Metaphor and organizing image"}, {"id": "5622b615-9e2c-48b4-9465-14e939ef6024", "type": "concept", "title": "Style, tone, and theatrical rules"}, {"id": "6be9667e-591b-4f10-b071-d1f0958f9218", "type": "concept", "title": "Concept statements and design vocabulary"}], "description": "Concept turns research into a clear design argument. Students practice moving from many references to one coherent production idea."}, {"id": "e720c304-7234-4a88-b295-40eb74be8676", "type": "subtopic", "title": "Iteration and critique", "children": [{"id": "bf48e50a-c310-4f46-a064-1afac0253f4e", "type": "concept", "title": "Thumbnail studies"}, {"id": "ca03af6f-d3a3-4905-b2c1-70c2785e888e", "type": "concept", "title": "Peer critique protocols"}, {"id": "04ad077f-c725-4878-a2e5-6902b5ab22df", "type": "concept", "title": "Revision logs and decision rationale"}], "description": "Design improves through revision. Students learn to test choices, receive critique, and refine without losing the core idea."}]}, {"id": "5cea4df6-7563-4938-8d45-622b65f96c28", "type": "topic", "title": "Script Analysis for Designers", "description": "Designers read scripts for visible and invisible demands: space, time, action, atmosphere, bodies, sound, objects, and transformation.", "children": [{"id": "4bdaaaac-5228-421d-bcb1-8139ce0dab08", "type": "subtopic", "title": "Given circumstances and world of the play", "children": [{"id": "c481b38b-1630-4abd-8097-dea20369b5fb", "type": "concept", "title": "Place and period"}, {"id": "d0580d9e-8afd-488c-bb1a-546ffc47c28c", "type": "concept", "title": "Social class and institutions"}, {"id": "23681f53-5284-45db-be7d-508f53b04f08", "type": "concept", "title": "Weather, season, and time"}], "description": "Students learn to identify the facts that every design must honor or intentionally transform."}, {"id": "32e7c738-8df3-4bef-b441-1af8f47bb6cc", "type": "subtopic", "title": "Dramatic action and structure", "children": [{"id": "c32dd2d1-d5b1-4c45-92dc-afb3bbd8e45d", "type": "concept", "title": "Events and turning points"}, {"id": "0c608bb4-4123-4e87-b398-3c50a8186d9e", "type": "concept", "title": "Beats and tempo"}, {"id": "2268e287-f22c-48dc-b942-29f095e2735f", "type": "concept", "title": "Scene transitions"}], "description": "The goal is to understand how design supports conflict, change, and rhythm rather than decorating scenes."}, {"id": "95631db5-3ef3-425f-ac08-14d262328188", "type": "subtopic", "title": "Character and social identity", "children": [{"id": "123d7fc8-11be-48a8-8e6a-fb6a3c41b388", "type": "concept", "title": "Character research"}, {"id": "92b9c75d-94c4-4959-8970-99c17b014e44", "type": "concept", "title": "Costume and object biographies"}, {"id": "506ec214-528d-4be1-915b-52236e590b61", "type": "concept", "title": "Power, identity, and representation"}], "description": "Design choices reveal how characters move through status, desire, labor, culture, and community."}, {"id": "2add15fd-8c4c-4caa-9bdb-5ef4405db0b2", "type": "subtopic", "title": "Designable moments", "children": [{"id": "3171759a-7381-4244-b46b-3d3eade4e546", "type": "concept", "title": "Entrances and exits"}, {"id": "ef9f5d35-2a45-45d8-918f-507263835f8b", "type": "concept", "title": "Reveals and transformations"}, {"id": "46f00e40-db20-43c1-bdf2-089fe99b97fe", "type": "concept", "title": "Silence, darkness, and sonic shifts"}], "description": "Students identify where scenery, light, costume, sound, and props can actively tell the story."}]}, {"id": "b97da1ff-78ac-49af-9d5d-3b480d903a58", "type": "topic", "title": "Scenic Design Fundamentals", "description": "Scenic design gives the production a spatial argument. Students learn how scale, architecture, texture, line, and movement shape the audience's reading of the play.", "children": [{"id": "e5d88e20-c4a2-4c25-9ba2-41c2ab8bf3f4", "type": "subtopic", "title": "Stage space and composition", "children": [{"id": "adeb06fa-dad8-4650-805b-a4855c95f637", "type": "concept", "title": "Proportion and balance"}, {"id": "e8ff1870-8465-4b29-8029-ecd648b2fd88", "type": "concept", "title": "Sightlines and focus"}, {"id": "b1fa1bc8-3ee5-43ec-b637-142709326a37", "type": "concept", "title": "Positive and negative space"}], "description": "Students learn how the audience reads space and how a set can organize attention, status, and action."}, {"id": "9e0282ab-c0f9-404d-93cc-ea223c834285", "type": "subtopic", "title": "Ground plans and models", "children": [{"id": "b9105237-a148-4c29-9ea0-76a29fb2d448", "type": "concept", "title": "Scale and measurement"}, {"id": "e4c1f1ac-cd35-40c6-bd9d-d0c2f57c24ca", "type": "concept", "title": "Traffic and blocking"}, {"id": "d9cffab3-e6dc-4afc-a0b0-49945f674148", "type": "concept", "title": "White models and presentation models"}], "description": "The point is to make ideas testable. Students translate imagination into scaled documents that directors, actors, and shops can use."}, {"id": "a612d6bc-e473-4d3e-8c43-b4e45e649b8f", "type": "subtopic", "title": "Materials, texture, and color", "children": [{"id": "6c1c7521-93d8-4dcc-aac4-a2c740c63ede", "type": "concept", "title": "Paint treatments"}, {"id": "47171746-382d-4a31-a5aa-8ea62655bcb2", "type": "concept", "title": "Fabrication materials"}, {"id": "943e0b1f-40cd-4305-8258-b42fedca1c5e", "type": "concept", "title": "Palette and visual metaphor"}], "description": "Scenic surfaces carry meaning and practical consequences. Students connect aesthetic choices to budget, build, durability, and theatrical illusion."}, {"id": "b745b9e8-d874-4d97-9098-1c340d437941", "type": "subtopic", "title": "Scene shifts and stage mechanics", "children": [{"id": "817a7435-bdfe-4e47-87f0-7e52b006a35e", "type": "concept", "title": "Wagons, tracks, and turntables"}, {"id": "e7119e67-04d5-43d4-9759-6d8bd41c8601", "type": "concept", "title": "Flying and rigging basics"}, {"id": "9e9ded99-f4e9-45e2-97ca-b1301e75687a", "type": "concept", "title": "Crew choreography and safety"}], "description": "Design includes how the world changes. Students study transitions as part of storytelling, not just logistics."}]}, {"id": "2d23a482-137a-4edd-b53e-0aa2e39be189", "type": "topic", "title": "Lighting Design Fundamentals", "description": "Lighting makes the audience see, feel, and follow. Students learn how angle, color, intensity, time, and cue structure create the visual score of performance.", "children": [{"id": "6ba49b09-7827-4cf8-8638-87b215553b8c", "type": "subtopic", "title": "Functions of stage lighting", "children": [{"id": "8ab855e2-3472-43b9-9d38-17903089d7f3", "type": "concept", "title": "Visibility and selective focus"}, {"id": "3566beaf-712d-40af-9a73-66b29b7f8086", "type": "concept", "title": "Modeling bodies and space"}, {"id": "d4452ee9-c09d-44b7-8196-9bfcade9ba48", "type": "concept", "title": "Mood, style, and atmosphere"}], "description": "Students learn the practical and expressive purposes of light: visibility, focus, form, mood, rhythm, and environment."}, {"id": "afd3e397-75a4-44eb-83c8-256f0cf86665", "type": "subtopic", "title": "Color, angle, and instrument basics", "children": [{"id": "b50179e3-7ac6-4193-8389-2f42530b7c2d", "type": "concept", "title": "Fixture families"}, {"id": "f802da3e-ba78-45f2-875d-cedd862abb8d", "type": "concept", "title": "Hanging positions"}, {"id": "dbd517e2-70ba-4fc4-ae8c-3b7150c4db3c", "type": "concept", "title": "Gel, LED color, and color temperature"}], "description": "The point is to understand the tools before composing with them. Students connect equipment choices to visual effect."}, {"id": "52fcb0c2-6983-4ea0-8251-4fa0d88a87f7", "type": "subtopic", "title": "Cueing and time", "children": [{"id": "810adbec-c90f-4d34-8b1e-451833c71af3", "type": "concept", "title": "Cue structure"}, {"id": "75c33981-48e8-40e4-9297-d3001632a2ab", "type": "concept", "title": "Fades and blackouts"}, {"id": "ef89cf78-2988-4418-876e-8e10036c5a8e", "type": "concept", "title": "Cue sheets and magic sheets"}], "description": "Lighting design unfolds in time. Students practice making transitions that support dramatic rhythm and audience attention."}, {"id": "d9bccb5d-f579-4998-93fb-e500221a1eec", "type": "subtopic", "title": "Lighting paperwork", "children": [{"id": "bbc08366-2726-4f13-9654-4563858b09b6", "type": "concept", "title": "Light plot"}, {"id": "4b997885-fce2-4894-895b-abb49d32a7e0", "type": "concept", "title": "Channel hookup"}, {"id": "c3b50057-7d3b-46d3-bff8-0f0e2b2ee7d2", "type": "concept", "title": "Focus notes and instrument schedule"}], "description": "Students learn professional documentation so a design can be hung, focused, programmed, and maintained."}]}, {"id": "34f89064-35dd-4849-9a4c-600e22434f48", "type": "topic", "title": "Costume Design Fundamentals", "description": "Costume design places character, body, culture, and story in motion. Students learn to design clothing as action, identity, period, and performance technology.", "children": [{"id": "cdee6b1c-2890-4471-acb4-edce43811503", "type": "subtopic", "title": "Character, body, and silhouette", "children": [{"id": "bf38619e-2351-4163-80da-f29e4aba2a6e", "type": "concept", "title": "Silhouette and proportion"}, {"id": "df5a75f5-0d41-4f4e-bbf0-82485793818c", "type": "concept", "title": "Actor movement and comfort"}, {"id": "680626b8-0464-404c-bb2c-e65d752be714", "type": "concept", "title": "Character arcs through dress"}], "description": "Students learn how clothing communicates status, transformation, age, labor, desire, and relationship before a character speaks."}, {"id": "f663c028-f771-4660-8c0c-8561fb598cfd", "type": "subtopic", "title": "Period and cultural research", "children": [{"id": "7faedf4f-41fa-4c75-bba0-10cdbd5315ce", "type": "concept", "title": "Historic clothing systems"}, {"id": "7d8391dd-9330-4c13-a015-0e641bb0e46d", "type": "concept", "title": "Cultural context and consultation"}, {"id": "41224bfb-e614-413f-b1c6-a54905de1884", "type": "concept", "title": "Avoiding stereotype and costume cliche"}], "description": "The aim is accuracy with interpretation. Students practice respectful, specific research rather than generic historical or cultural shorthand."}, {"id": "7ad66d45-9dbd-4b84-9136-62cfef3eb421", "type": "subtopic", "title": "Textiles, color, and construction logic", "children": [{"id": "e18e8cfa-c239-4be5-b033-94c7c4fafa73", "type": "concept", "title": "Fabric drape and texture"}, {"id": "30b55cfd-ddc2-4759-b852-bc8ba255e69e", "type": "concept", "title": "Palette and symbolism"}, {"id": "3d398ba4-995c-4c22-b5bd-e3809727fec8", "type": "concept", "title": "Build, pull, rent, or buy decisions"}], "description": "Students connect image to physical reality: fabric behavior, quick changes, maintenance, and shop feasibility."}, {"id": "9fcf3572-8faa-4f8f-a50c-6f35aca3e571", "type": "subtopic", "title": "Costume rendering and communication", "children": [{"id": "6021ee75-2e21-4c28-8e7e-23c19c568885", "type": "concept", "title": "Figure drawing basics"}, {"id": "e273a61d-848f-44fe-a450-ff14e8f06847", "type": "concept", "title": "Swatches and research plates"}, {"id": "c8132bbc-7717-4279-a277-00f9adb86827", "type": "concept", "title": "Costume plots and change charts"}], "description": "The point is to make character choices legible to directors, actors, drapers, and shops."}]}, {"id": "7280365c-e041-43f1-b1f9-f1d91450eed0", "type": "topic", "title": "Sound Design Fundamentals", "description": "Sound design builds atmosphere, rhythm, memory, place, and emotional pressure. Students learn to listen dramaturgically and design a sonic world.", "children": [{"id": "a2a85860-13fa-4832-89df-4bbc4ec7632c", "type": "subtopic", "title": "Sonic dramaturgy", "children": [{"id": "e33f0d36-1fb2-41dc-bfd2-c7d7c1038a92", "type": "concept", "title": "Motifs and recurring sounds"}, {"id": "e9acebd2-91b6-42cf-aa54-5c554e0cf31f", "type": "concept", "title": "Silence as a design choice"}, {"id": "8ee3f0ba-1fab-432f-869a-9ad4b742ed4a", "type": "concept", "title": "Point of view and memory"}], "description": "Students learn why sound belongs in the design conversation from the beginning, not only as an effect added late."}, {"id": "f377d82d-7a69-4c66-a5eb-b8c41341be2b", "type": "subtopic", "title": "Music, effects, and ambience", "children": [{"id": "cb7f03c2-6c65-4b2e-8646-eedfb3c6d0ee", "type": "concept", "title": "Diegetic and non-diegetic sound"}, {"id": "f06088e6-9bf5-4497-a7d4-b4340f3539dd", "type": "concept", "title": "Transitions and underscoring"}, {"id": "cc810da5-66ec-4bab-99f1-f9cdc0892e90", "type": "concept", "title": "Environmental beds"}], "description": "The goal is to distinguish categories of sound and understand how each affects storytelling."}, {"id": "e49b9ed2-75f4-403b-a55f-0333a6a92557", "type": "subtopic", "title": "Systems and playback basics", "children": [{"id": "15e6a8e2-2b54-4a1c-bd1a-6ee53dafdc55", "type": "concept", "title": "Speakers and coverage"}, {"id": "e2c61c4f-7647-4703-a204-b9496e827813", "type": "concept", "title": "Microphones and reinforcement"}, {"id": "932a79c3-9365-44a6-a2bb-cfe48f9e9fde", "type": "concept", "title": "Playback software and cue stacks"}], "description": "Students learn enough technical vocabulary to collaborate with engineers and make practical choices."}, {"id": "0892b379-6065-4847-961a-c78d34d6abdb", "type": "subtopic", "title": "Cue documentation", "children": [{"id": "60fe3287-d66c-46e0-bac4-9c0e4173b08b", "type": "concept", "title": "Cue lists"}, {"id": "458aa849-9d7a-4fbb-9939-020c03231f40", "type": "concept", "title": "Copyright and licensing notes"}, {"id": "ead36e93-5387-49b7-9ded-c7c113e6537b", "type": "concept", "title": "Tech rehearsal updates"}], "description": "Sound choices must be repeatable. Students practice cue sheets, source logs, and rehearsal notes."}]}, {"id": "5e192ad3-619d-43cb-82e8-a0c48faa3b8b", "type": "topic", "title": "Rendering and Presentation", "description": "Presentation is how a design becomes shareable. Students learn visual and verbal methods for persuading collaborators and making choices clear.", "children": [{"id": "bffe0040-fd73-43e4-b6b6-450e0e3d3774", "type": "subtopic", "title": "Drawing, drafting, and model-making", "children": [{"id": "c525faa5-d132-4055-8001-e869547921f1", "type": "concept", "title": "Sketching and thumbnails"}, {"id": "0d19173c-8314-4d45-ba92-cb9e36efc423", "type": "concept", "title": "Orthographic drafting"}, {"id": "5577a425-2013-43c2-9a4f-7fca28680da2", "type": "concept", "title": "Physical and digital models"}], "description": "Students learn multiple ways to represent scale, mood, detail, and spatial relationships."}, {"id": "35201cfd-de0b-4efc-a404-68f4be5fe256", "type": "subtopic", "title": "Mood boards and visual research boards", "children": [{"id": "0c28e093-eb1f-4044-8e1f-f8f8429fd508", "type": "concept", "title": "Image selection"}, {"id": "af0b4dfc-f4f3-4c57-bac8-de6e35501db1", "type": "concept", "title": "Palette and texture boards"}, {"id": "7c599a5d-bc24-4747-b68b-77c1438e2e45", "type": "concept", "title": "Source labeling and research ethics"}], "description": "The point is to curate evidence so the production team can see the proposed world and its rules."}, {"id": "5944251e-9681-4fae-b391-bdb847138037", "type": "subtopic", "title": "Digital visualization", "children": [{"id": "c8eb4b6f-b063-4ba3-baf6-e42c30b6cc90", "type": "concept", "title": "Vector and raster workflows"}, {"id": "069790d6-3cd3-4b58-8d9e-294bc998f58b", "type": "concept", "title": "3D massing and rendering"}, {"id": "d413b275-67f3-4bae-9e93-8b510ac8706b", "type": "concept", "title": "Projection and media mockups"}], "description": "Students practice contemporary tools while keeping design thinking ahead of software technique."}, {"id": "61a4bb12-226b-4197-a735-8d47a882ac78", "type": "subtopic", "title": "Critique and presentation language", "children": [{"id": "3e06835e-443d-4035-b9aa-64fa74057649", "type": "concept", "title": "Design statements"}, {"id": "81e30f09-9ae3-4c0e-9363-7e612cccf26d", "type": "concept", "title": "Responding to notes"}, {"id": "81e74bb1-c2f6-400e-8c91-ca1242fbfafc", "type": "concept", "title": "Portfolio-ready documentation"}], "description": "Designers must explain choices without over-defending them. Students learn concise, specific, collaborative presentation habits."}]}, {"id": "76367919-0c9b-4d36-859d-7e2ebfccd8c8", "type": "topic", "title": "Collaboration with the Director", "description": "Theater design is collaborative authorship. Students learn how to align strong design ideas with a director's staging, actor process, dramaturgy, and production reality.", "children": [{"id": "67053643-e25f-4021-80ef-f16e1593eb35", "type": "subtopic", "title": "Director-designer conversations", "children": [{"id": "ddafdc42-eb95-45d1-806a-c4159b6d0af6", "type": "concept", "title": "Initial meeting prompts"}, {"id": "747763f1-037a-40a9-9ea3-42deec0eb8b6", "type": "concept", "title": "Shared vocabulary"}, {"id": "642a76d7-c14b-4d52-94ae-0dfe17137781", "type": "concept", "title": "Concept alignment"}], "description": "Students learn to ask useful questions, listen for priorities, and translate abstract goals into concrete design paths."}, {"id": "02b49d16-33a2-4c19-bdae-1d3e4bdbabc7", "type": "subtopic", "title": "Production meetings", "children": [{"id": "ef7465d8-554f-4860-9f64-cb84a16d359e", "type": "concept", "title": "Meeting reports"}, {"id": "5b71c406-d624-49ff-bfcc-dd0a8288bb68", "type": "concept", "title": "Open questions and action items"}, {"id": "5c07d578-9487-4166-952f-dce2a9f39320", "type": "concept", "title": "Interdepartmental dependencies"}], "description": "The point is to keep creative and technical decisions moving together across departments."}, {"id": "5fc47291-7970-4b68-a601-a8ff13b02c4a", "type": "subtopic", "title": "Negotiation and feedback", "children": [{"id": "2fcacd44-4cfe-49af-9c48-c8c50cab13a3", "type": "concept", "title": "Budget and schedule tradeoffs"}, {"id": "7f3b1501-3e21-4c43-bae8-77ca05897b54", "type": "concept", "title": "Actor and stage management needs"}, {"id": "eeea13d3-bef3-44be-aca7-69502c041afd", "type": "concept", "title": "Documenting revisions"}], "description": "Students learn that notes are part of craft. They practice preserving design intent while solving real production problems."}, {"id": "737ebef8-8caf-43a2-835e-aabf1bdf581d", "type": "subtopic", "title": "Dramaturgical responsibility", "children": [{"id": "850e9081-e2c5-4084-b6dc-dae8a5ff5541", "type": "concept", "title": "Representation and harm reduction"}, {"id": "e19c3d4e-0e41-4216-a859-f7b9e28d099b", "type": "concept", "title": "Consultants and community knowledge"}, {"id": "88fcee4c-c313-4471-b680-a31fe25aabde", "type": "concept", "title": "Audience context"}], "description": "Design collaboration includes ethical and cultural accountability for what appears on stage."}]}, {"id": "ac81455a-0ac5-4d4c-8e56-ce46485039a6", "type": "topic", "title": "Design for Different Spaces", "description": "A design changes when the audience relationship changes. Students learn to adapt theatrical ideas to architecture, scale, proximity, mobility, technology, and access.", "children": [{"id": "5b83ff41-99b0-4d51-91a7-ea11c59f4e58", "type": "subtopic", "title": "Stage configurations", "children": [{"id": "eaa0143f-5430-47ec-8714-ce49846de834", "type": "concept", "title": "Sightlines"}, {"id": "5c42aa95-b97d-4c02-b7d3-b2bf75ae387e", "type": "concept", "title": "Entrances and circulation"}, {"id": "5f67ddce-bd10-45ee-bc4e-502130f81247", "type": "concept", "title": "Backstage and storage limits"}], "description": "Students compare how proscenium, thrust, arena, and black box spaces shape composition and actor-audience relationships."}, {"id": "59215e5f-665d-474a-9b47-afeffd8b1e62", "type": "subtopic", "title": "Site-specific and immersive design", "children": [{"id": "db364e36-c69c-456c-9da1-565741e46bdb", "type": "concept", "title": "Audience pathway"}, {"id": "ad55c28d-cac8-4549-93ad-f4873dc81f61", "type": "concept", "title": "Environmental storytelling"}, {"id": "5d17f2b9-1cb9-4483-8ea1-942ef2689426", "type": "concept", "title": "Permissions, safety, and weather"}], "description": "The goal is to treat location as a co-author rather than a neutral container."}, {"id": "a644700f-9a17-4cb0-841f-725111223043", "type": "subtopic", "title": "Touring and resource-limited design", "children": [{"id": "898db6c8-a3a7-474f-aa48-32f13b295ef4", "type": "concept", "title": "Portability and packing"}, {"id": "6635d6ef-8b9d-4bd1-8c8e-3eec45abff0e", "type": "concept", "title": "Modular scenery"}, {"id": "89bb5f41-fa01-4f57-ae17-b4ecc9e8d7db", "type": "concept", "title": "Local labor and venue adaptation"}], "description": "Students learn how constraints can sharpen invention while preserving the production's essential design idea."}, {"id": "9534e720-59d7-4eb2-ba08-0e61fbecc2c0", "type": "subtopic", "title": "Accessibility and inclusive experience", "children": [{"id": "9e9b8fb9-8fd7-4f0f-911b-19197c413cfd", "type": "concept", "title": "Accessible routes and seating"}, {"id": "5c754edb-ba83-480b-8265-510de22fc9ac", "type": "concept", "title": "Captioning and audio description interfaces"}, {"id": "c2f43bf1-94df-4d26-b21d-4147f33e6994", "type": "concept", "title": "Sensory considerations"}], "description": "Design must consider who can enter, perceive, and participate in the event."}]}, {"id": "af8d4117-28eb-412c-afeb-3455c4342f76", "type": "topic", "title": "Realizing a Design", "description": "Realization is where design meets shops, crews, time, money, safety, and audiences. Students learn how artistic choices become repeatable production practice.", "children": [{"id": "83abc25a-ebc2-4581-aadb-4bb60cd44dfa", "type": "subtopic", "title": "Budgets, calendars, and build planning", "children": [{"id": "16cd7a6b-f867-4fb8-bf48-87349a12a9e2", "type": "concept", "title": "Cost estimates"}, {"id": "2282a14c-3385-4b4d-8461-d7aa610ecbc0", "type": "concept", "title": "Build schedules"}, {"id": "d3fbcb7d-930a-4752-89cb-fd3b166f44f4", "type": "concept", "title": "Rental, purchase, and fabrication choices"}], "description": "Students learn to make creative decisions with practical consequences visible early."}, {"id": "d8260764-bea1-407d-886c-ac5b31e9c9a4", "type": "subtopic", "title": "Shop collaboration and technical direction", "children": [{"id": "fcd38624-d17c-474a-8425-780e4467b8d3", "type": "concept", "title": "Drafting handoff"}, {"id": "c9d5b0da-d984-4d91-928d-4dbb0e77be83", "type": "concept", "title": "Material tests"}, {"id": "8021f420-78ae-4b7f-b02b-41b3fa518dc3", "type": "concept", "title": "Technical problem solving"}], "description": "The point is to respect the expertise of makers and technicians while keeping the design's intent clear."}, {"id": "e4e71611-37aa-4235-8637-f969f08caa9e", "type": "subtopic", "title": "Tech rehearsal and previews", "children": [{"id": "4c5c352b-767e-46bf-87a6-fc92cead8727", "type": "concept", "title": "Cue-to-cue"}, {"id": "1c5db6c1-3bfc-4702-bfcc-0fe78147aef1", "type": "concept", "title": "Dress rehearsal notes"}, {"id": "027be96e-db52-4b1b-a752-b02cd5947667", "type": "concept", "title": "Prioritizing fixes"}], "description": "Students learn how designs change under live conditions and how to take notes productively."}, {"id": "757fd7e1-9a85-4835-b5a0-664c924e4ce9", "type": "subtopic", "title": "Safety, sustainability, and professional practice", "children": [{"id": "1509a12f-3baf-4f6a-92d4-5c740ac3951b", "type": "concept", "title": "Rigging and electrical safety awareness"}, {"id": "f054cea2-afe3-461f-b6bf-bb42be61cf48", "type": "concept", "title": "Sustainable materials and reuse"}, {"id": "0296c4e4-7012-48a3-a121-981d9221d5dc", "type": "concept", "title": "Portfolio reflection and archival documentation"}], "description": "Design includes care for workers, performers, materials, and communities."}]}], "dbBacked": true}$dthtjson$::jsonb,
